    // Pristine replaceMacros asks for the last ordinary Chat message even when
    // called by Worlds. Preserve that read behavior without allowing its
    // legacy getCurrentSession repair path to mutate the authoritative host.
    function getCurrentSession() {
        const session = host?.peekCurrentChatSession?.() || null;
        return session ? safeJsonClone(session) : null;
    }

    async function getOpenRouterModels() {
        if (!host?.getModelCatalog) throw new Error('Stock Worlds host model catalog is unavailable');
        const force = modelCatalogLoadedOnce && openRouterModels.length === 0 && modelCatalogSource === null;
        const models = await host.getModelCatalog({ force });
        openRouterModels = Array.isArray(models) ? models : [];
        modelCatalogSource = host?.getModelCatalogSource?.() || null;
        modelCatalogLoadedOnce = true;
        return openRouterModels;
    }

// --- Horde Persistence (IndexedDB) ---
const DB_NAME = 'HordeStudioStockWorlds17Pass0DB';
const DB_VERSION = 1;
const STORE_NAME = 'state';
const HordeDB = {
    db: null,
    async init() {
        return new Promise((resolve, reject) => {
            const request = indexedDB.open(DB_NAME, DB_VERSION);
            request.onerror = () => reject(request.error || new Error('Database error'));
            request.onupgradeneeded = (e) => {
                const db = e.target.result;
                if (!db.objectStoreNames.contains(STORE_NAME)) {
                    db.createObjectStore(STORE_NAME);
                }
            };
            request.onsuccess = (e) => {
                this.db = e.target.result;
                resolve();
            };
        });
    },
    async get(key) {
        if (!this.db) throw new Error('Database is not initialized');
        return new Promise((resolve, reject) => {
            const transaction = this.db.transaction([STORE_NAME], 'readonly');
            const request = transaction.objectStore(STORE_NAME).get(key);
            request.onsuccess = () => resolve(request.result);
            request.onerror = () => reject(request.error || transaction.error || new Error(`Unable to read ${key}`));
        });
    },
    async set(key, value) {
        if (!this.db) throw new Error('Database is not initialized');
        return new Promise((resolve, reject) => {
            const transaction = this.db.transaction([STORE_NAME], 'readwrite');
            const request = transaction.objectStore(STORE_NAME).put(value, key);
            transaction.oncomplete = () => resolve();
            transaction.onerror = () => reject(transaction.error || request.error || new Error(`Unable to save ${key}`));
            transaction.onabort = () => reject(transaction.error || new Error(`Saving ${key} was aborted`));
        });
    },
    async delete(key) {
        if (!this.db) throw new Error('Database is not initialized');
        return new Promise((resolve, reject) => {
            const transaction = this.db.transaction([STORE_NAME], 'readwrite');
            const request = transaction.objectStore(STORE_NAME).delete(key);
            transaction.oncomplete = () => resolve();
            transaction.onerror = () => reject(transaction.error || request.error || new Error(`Unable to delete ${key}`));
            transaction.onabort = () => reject(transaction.error || new Error(`Deleting ${key} was aborted`));
        });
    },
    async setMultiple(kvMap) {
        if (!this.db) throw new Error('Database is not initialized');
        return new Promise((resolve, reject) => {
            const transaction = this.db.transaction([STORE_NAME], 'readwrite');
            const store = transaction.objectStore(STORE_NAME);
            for (const [key, value] of Object.entries(kvMap)) {
                store.put(value, key);
            }
            transaction.oncomplete = () => resolve();
            transaction.onerror = () => reject(transaction.error || new Error('Unable to save application data'));
            transaction.onabort = () => reject(transaction.error || new Error('Saving application data was aborted'));
        });
    },
    close() {
        if (this.db) this.db.close();
        this.db = null;
    }
};

    async function persistStockStateSnapshot() {
        const savingWorldMedia = worldMediaDirty;
        const storedWorlds = (state.worlds || []).map(world => ({ ...world, mediaAssets: [] }));
        const visibleWorldIds = new Set(storedWorlds.map(world => world.id));
        const recovery = isPlainObject(state.worldRecoverySnapshots) ? state.worldRecoverySnapshots : {};
        lastPersistedWorldManifests.forEach(previous => {
            if (!isPlainObject(previous) || !previous.id || visibleWorldIds.has(previous.id)) return;
            recovery[previous.id] = {
                capturedAt: new Date().toISOString(),
                reason: 'World was absent from a later save',
                world: safeJsonClone(previous)
            };
        });
        state.worldRecoverySnapshots = Object.fromEntries(Object.entries(recovery)
            .sort((a, b) => String(b[1]?.capturedAt || '').localeCompare(String(a[1]?.capturedAt || '')))
            .slice(0, 30));
        const records = {
            worlds: storedWorlds,
            worldRecoverySnapshots: state.worldRecoverySnapshots,
            worldInstances: state.worldInstances,
            activeWorldId: state.activeWorldId,
            stockSettings: { ...stockSettings }
        };
        if (savingWorldMedia) {
            records.worldMediaAssets = Object.fromEntries((state.worlds || []).map(world => [
                world.id,
                safeJsonClone(Array.isArray(world.mediaAssets) ? world.mediaAssets : [])
            ]));
            worldMediaDirty = false;
        }
        try {
            await HordeDB.setMultiple(records);
            lastPersistedWorldManifests = safeJsonClone(storedWorlds);
            if (hostSettingsDirty || sharedHostStateRead) {
                await host?.persistHostState?.();
                hostSettingsDirty = false;
                sharedHostStateRead = false;
            }
        } catch (error) {
            if (savingWorldMedia) worldMediaDirty = true;
            throw error;
        }
    }

    async function saveState() {
        saveStateQueued = true;
        if (saveStateInFlight) return saveStateInFlight;
        saveStateInFlight = (async () => {
            do {
                saveStateQueued = false;
                await persistStockStateSnapshot();
            } while (saveStateQueued);
        })();
        try { await saveStateInFlight; }
        finally { saveStateInFlight = null; }
    }

    function repairStockWorldState() {
        worldLoadWarnings.clear();
        state.worldInstances = isPlainObject(state.worldInstances) ? state.worldInstances : {};
        state.worldRecoverySnapshots = isPlainObject(state.worldRecoverySnapshots) ? state.worldRecoverySnapshots : {};
        state.worlds = Array.isArray(state.worlds) ? state.worlds.filter(isPlainObject) : [];
        state.worlds.forEach((world, index) => {
            if (typeof world.id !== 'string' || !world.id.trim()) world.id = `world_recovered_${Date.now()}_${index}`;
            if (typeof world.name !== 'string' || !world.name.trim()) world.name = `Recovered World ${index + 1}`;
            world.locations = Array.isArray(world.locations) ? world.locations.filter(isPlainObject) : [];
            world.entities = Array.isArray(world.entities) ? world.entities.filter(isPlainObject) : [];
            world.lorebook = Array.isArray(world.lorebook) ? world.lorebook.filter(isPlainObject) : [];
            try { validateWorldData(world); }
            catch (error) { worldLoadWarnings.set(world.id, error.message || 'This world needs repair.'); }
            world.hudConfig = {
                showClock: true, showQuests: true, showLedger: true, showInventory: true,
                timeStep: 5, startTimeHours: 8, startTimeMinutes: 0,
                showDays: false, enableSchedules: false,
                ...(isPlainObject(world.hudConfig) ? world.hudConfig : {})
            };
            world.hudConfig.stats = Array.isArray(world.hudConfig.stats) ? world.hudConfig.stats : [];
            normalizeWorldGameRules(world);
            world.locations.forEach(location => { location.exits = location.exits || []; });
            world.entities.forEach(entity => {
                entity.secrets = entity.secrets || [];
                entity.schedule = entity.schedule || [];
            });
            normalizeAuthoredWorld(world);
        });
    }

    async function loadStockState() {
        await HordeDB.init();
        await HordeVectorMemory.init();
        STARTER_WORLDS.forEach((world, index) => { STARTER_WORLDS[index] = upgradeBundledWorldDefinition(world); });
        state.worlds = await HordeDB.get('worlds') || [];
        state.worldRecoverySnapshots = await HordeDB.get('worldRecoverySnapshots') || {};
        state.worldInstances = await HordeDB.get('worldInstances') || {};
        state.activeWorldId = await HordeDB.get('activeWorldId') || null;
        Object.assign(stockSettings, await HordeDB.get('stockSettings') || {});
        const storedWorldMedia = await HordeDB.get('worldMediaAssets') || {};
        state.worlds.forEach(world => {
            const separateAssets = Array.isArray(storedWorldMedia[world.id]) ? storedWorldMedia[world.id] : null;
            if (separateAssets) world.mediaAssets = separateAssets;
            else if ((world.mediaAssets || []).length) worldMediaDirty = true;
        });
        repairStockWorldState();
        lastPersistedWorldManifests = safeJsonClone(state.worlds.map(world => ({ ...world, mediaAssets: [] })));

        let changed = false;
        if (!state.worlds.length) {
            state.worlds = safeJsonClone(STARTER_WORLDS);
            stockSettings.seededWorldIds = STARTER_WORLDS.map(world => world.id);
            changed = true;
        }
        const offered = Array.isArray(stockSettings.includedWorldReceipts) ? stockSettings.includedWorldReceipts : [];
        for (const rawCandidate of pristineIncludedWorlds) {
            const candidate = upgradeBundledWorldDefinition(rawCandidate);
            const bundleId = String(candidate?.bundledId || '').trim();
            if (!bundleId || offered.includes(bundleId)) continue;
            if (!state.worlds.some(world => world?.bundledId === bundleId || world?.id === candidate.id)) {
                state.worlds.push(validateWorldData(candidate, `Included world ${bundleId}`));
                worldMediaDirty = true;
            }
            offered.push(bundleId);
            changed = true;
        }
        stockSettings.includedWorldReceipts = [...new Set(offered)];
        if (migrateStarterModelInheritance([], state.worlds, stockGlobalSettings)) changed = true;
        repairStockWorldState();
        if (changed || worldMediaDirty) await saveState();
    }

    function switchView(viewName) {
        if (!['worlds', 'worldStudio', 'worldPlay'].includes(viewName)) {
            host?.navigateHost?.(viewName);
            return;
        }
        state.view = viewName;
        ['worlds', 'worldStudio', 'worldPlay'].forEach(name => {
            document.getElementById(name === 'worlds' ? 'worlds-view' : name === 'worldStudio' ? 'world-studio-view' : 'world-play-view')
                ?.classList.toggle('hidden', name !== viewName);
        });
        if (viewName === 'worlds') renderWorlds();
        if (viewName === 'worldStudio' && !state.editingWorld) {
            if (state.activeWorldId) openWorldStudio(state.activeWorldId);
            else if (state.worlds.length) openWorldStudio(state.worlds[0].id);
            else createNewWorld();
        }
    }

// pristine app.js:4052-4627 (World statements only)
async function setupAIBuilderLogic() {
    await setupSearchableDropdown('w-');

    await setupConfigSearchableDropdown('w-');

    const searchWorld = document.getElementById('w-builder-model-search');
    if (searchWorld) {
        const defaultWorldModel = state.editingWorld?.model || 'google/gemini-2.5-pro';
        searchWorld.value = defaultWorldModel;
    }

    const btnGenWorld = document.getElementById('w-builder-generate-btn');
    if (btnGenWorld) {
        btnGenWorld.onclick = async () => {
            const promptText = document.getElementById('w-builder-prompt').value.trim();
            if (!promptText) return showToast("Please input a creative prompt dump first.", "error");

            if (!hasApiCredentials()) return showToast(`API Key is missing. Add your ${cloudProviderName()} key in Settings.`, "error");

            const modelId = document.getElementById('w-builder-model-search').value.trim() || 'google/gemini-2.5-pro';

            btnGenWorld.disabled = true;
            btnGenWorld.textContent = "⚡ Constructing Universe...";
            document.getElementById('w-builder-preview-box').classList.add('hidden');
            document.getElementById('w-builder-recovery-box').classList.add('hidden');
            
            const wDiagnosticEl = document.getElementById('w-builder-error-diagnostic');
            if (wDiagnosticEl) {
                wDiagnosticEl.classList.add('hidden');
                wDiagnosticEl.innerHTML = '';
            }
            
            const progressBox = document.getElementById('w-builder-progress-box');
            progressBox.classList.remove('hidden');
            const codeOutput = document.getElementById('w-builder-code-output');
            codeOutput.classList.remove('hidden');
            codeOutput.textContent = '';

            setBuilderStep('w-step-analyze', 'active');
            setBuilderStep('w-step-locations', 'pending');
            setBuilderStep('w-step-entities', 'pending');
            setBuilderStep('w-step-lore', 'pending');
            setBuilderStep('w-step-finalize', 'pending');

            const systemPrompt = `[SYSTEM MANDATE]
You are the Horde World Architect. Your sole function is to take the user's creative prompt and compile it into a single, fully structured JSON world object.

The output MUST be a single JSON object. Do not include any chat preamble, greeting, or conversational filler. Output only the JSON.

SCHEMA SPECIFICATION:
{
  "name": "World Name",
  "description": "A short, engaging description of the world setting.",
  "dmPrompt": "An extensive system prompt/persona for the Dungeon Master, detailing their narrative tone, rules of simulation, and interaction guidelines. Keep narration descriptive, sensory, and reactive.",
  "authorNote": "A brief style directive injected at a deep level to influence the AI narration style.",
  "locations": [
    {
      "id": "loc_unique_id",
      "name": "Location Name",
      "region": "Optional Region/Area Name",
      "description": "Vivid sensory description of what a player sees, hears, and smells upon arrival.",
      "exits": ["to Location Name B", "to Location Name C"],
      "secrets": []
    }
  ],
  "entities": [
    {
      "id": "ent_unique_id",
      "name": "Entity Name",
      "type": "npc" | "item",
      "description": "Vivid description of the NPC or item, outlining behavior, dialogue style, or item attributes."
    }
  ],
  "lorebook": [
    {
      "keyword": "A key term (magic, faction, event, place, etc.)",
      "text": "Detailed information, rules, or legends about this key term."
    }
  ]
}

CRITICAL STRUCTURAL RULE:
In the locations exits array, list paths linking locations together in a logical, navigable way. Ensure exits are bi-directional (e.g. if A has an exit to B, B should have an exit to A). All location exits must correspond to locations created in the same JSON.

Respond ONLY with a valid JSON block.`;

            let timerInterval;
            let fullText = '';
            try {
                setTimeout(() => setBuilderStep('w-step-analyze', 'success'), 1200);
                setTimeout(() => setBuilderStep('w-step-locations', 'active'), 1300);

                const requestBody = {
                    model: modelId,
                    messages: [
                        { role: 'system', content: systemPrompt },
                        { role: 'user', content: promptText }
                    ],
                    temperature: 0.7,
                    stream: true
                };

                const matchingModel = openRouterModels.find(m => m.id === modelId);
                if (matchingModel && matchingModel.supported_parameters?.includes('response_format')) {
                    requestBody.response_format = { type: 'json_object' };
                }

                const response = await fetch(apiBase() + '/chat/completions', {
                    method: 'POST',
                    headers: {
                        ...authHeaders(),
                        'Content-Type': 'application/json',
                        ...attributionHeaders()
                    },
                    body: JSON.stringify(requestBody)
                });

                if (!response.ok) {
                    const errData = await response.json().catch(() => ({}));
                    throw new Error(errData.error?.message || response.statusText);
                }

                const reader = response.body.getReader();
                const decoder = new TextDecoder();
                let stepTimer = 0;

                timerInterval = setInterval(() => {
                    stepTimer++;
                    if (stepTimer === 6) {
                        setBuilderStep('w-step-locations', 'success');
                        setBuilderStep('w-step-entities', 'active');
                    } else if (stepTimer === 12) {
                        setBuilderStep('w-step-entities', 'success');
                        setBuilderStep('w-step-lore', 'active');
                    } else if (stepTimer === 18) {
                        setBuilderStep('w-step-lore', 'success');
                        setBuilderStep('w-step-finalize', 'active');
                    }
                }, 1000);

                while (true) {
                    const { done, value } = await reader.read();
                    if (done) break;
                    
                    const chunk = decoder.decode(value, { stream: true });
                    const lines = chunk.split('\n');
                    
                    for (const line of lines) {
                        if (line.startsWith('data: ')) {
                            const dataStr = line.slice(6).trim();
                            if (dataStr === '[DONE]') break;
                            
                            try {
                                const parsed = JSON.parse(dataStr);
                                const token = parsed.choices[0]?.delta?.content || '';
                                fullText += token;
                                codeOutput.textContent = fullText;
                                codeOutput.scrollTop = codeOutput.scrollHeight;
                            } catch (e) {}
                        }
                    }
                }

                clearInterval(timerInterval);

                setBuilderStep('w-step-locations', 'success');
                setBuilderStep('w-step-entities', 'success');
                setBuilderStep('w-step-lore', 'success');
                setBuilderStep('w-step-finalize', 'active');

                const parsedWorld = validateWorldData(extractJSON(fullText), 'Generated world');
                setBuilderStep('w-step-finalize', 'success');
                
                state.generatedWorld = parsedWorld;

                const warningList = validateWorldPathways(parsedWorld);
                const warningContainer = document.getElementById('w-builder-warning-container');
                if (warningContainer) {
                    warningContainer.innerHTML = '';
                    if (warningList.length > 0) {
                        warningContainer.innerHTML = `
                            <div class="builder-warning-box">
                                <span>⚠️ Pathway Check: ${warningList.length} warning(s) found. Exits will still connect in simulation.</span>
                            </div>
                        `;
                        console.warn("World Generator Path Warnings:", warningList);
                    }
                }

                document.getElementById('w-preview-identity').textContent = `${parsedWorld.name || 'Unnamed'} — ${parsedWorld.description || 'No description'}`;
                document.getElementById('w-preview-locations-count').textContent = `${parsedWorld.locations?.length || 0} locations`;
                document.getElementById('w-preview-entities-count').textContent = `${parsedWorld.entities?.length || 0} items/NPCs`;
                document.getElementById('w-preview-lore-count').textContent = `${parsedWorld.lorebook?.length || 0} entries`;

                progressBox.classList.add('hidden');
                document.getElementById('w-builder-preview-box').classList.remove('hidden');
                showToast("Universe created successfully!", "success");

            } catch (err) {
                if (timerInterval) clearInterval(timerInterval);
                console.error("AI Generation Error:", err);
                showToast("Building failed: " + err.message, "error");
                codeOutput.textContent += `\n\n[ERROR]: ${err.message}`;
                
                // Activate recovery box if we have a generated response
                if (fullText) {
                    const recoveryBox = document.getElementById('w-builder-recovery-box');
                    const recoveryTextarea = document.getElementById('w-builder-recovery-textarea');
                    if (recoveryBox && recoveryTextarea) {
                        recoveryBox.classList.remove('hidden');
                        recoveryTextarea.value = fullText;
                        codeOutput.scrollTop = codeOutput.scrollHeight;
                        displayJSONErrorDiagnostic('w-', fullText, err.message);
                    }
                }
            } finally {
                btnGenWorld.disabled = false;
                btnGenWorld.textContent = "✨ Build World";
            }
        };
    }

    const btnApplyWorld = document.getElementById('w-builder-apply-btn');
    if (btnApplyWorld) {
        btnApplyWorld.onclick = async () => {
            if (!state.generatedWorld) return;
            
            const g = state.generatedWorld;
            state.editingWorld.name = g.name || state.editingWorld.name;
            state.editingWorld.description = g.description || state.editingWorld.description;
            state.editingWorld.dmPrompt = g.dmPrompt || state.editingWorld.dmPrompt;
            state.editingWorld.authorNote = g.authorNote || state.editingWorld.authorNote;
            
            state.editingWorld.locations = g.locations || [];
            state.editingWorld.entities = g.entities || [];
            state.editingWorld.lorebook = g.lorebook || [];

            openWorldStudio();

            const basicsTab = document.querySelector('.world-studio-tab[data-tab="w-basics"]');
            if (basicsTab) basicsTab.click();

            await saveWorld();
            showToast("AI World settings applied successfully!", "success");
        };
    }

    const btnMergeWorld = document.getElementById('w-builder-merge-btn');
    if (btnMergeWorld) {
        btnMergeWorld.onclick = async () => {
            if (!state.generatedWorld) return;
            
            const g = state.generatedWorld;
            const current = state.editingWorld;

            const currentLocNames = (current.locations || []).map(l => l.name.toLowerCase());
            (g.locations || []).forEach(newLoc => {
                if (!currentLocNames.includes(newLoc.name.toLowerCase())) {
                    current.locations.push(newLoc);
                } else {
                    const existingLoc = current.locations.find(l => l.name.toLowerCase() === newLoc.name.toLowerCase());
                    if (existingLoc) {
                        const mergedExits = Array.from(new Set([...(existingLoc.exits || []), ...(newLoc.exits || [])]));
                        existingLoc.exits = mergedExits;
                    }
                }
            });

            const currentEntNames = (current.entities || []).map(e => e.name.toLowerCase());
            (g.entities || []).forEach(newEnt => {
                if (!currentEntNames.includes(newEnt.name.toLowerCase())) {
                    newEnt.id = "ent_" + Date.now() + "_" + Math.floor(Math.random() * 1000);
                    current.entities.push(newEnt);
                }
            });

            const currentLoreKeywords = (current.lorebook || []).map(l => l.keyword.toLowerCase());
            (g.lorebook || []).forEach(newL => {
                if (!currentLoreKeywords.includes(newL.keyword.toLowerCase())) {
                    current.lorebook.push(newL);
                }
            });

            openWorldStudio();

            const locsTab = document.querySelector('.world-studio-tab[data-tab="w-locations"]');
            if (locsTab) locsTab.click();

            await saveWorld();
            showToast("New region, NPCs, and lore merged successfully!", "success");
        };
    }

    const btnWRecoveryReparse = document.getElementById('w-builder-recovery-reparse-btn');
    if (btnWRecoveryReparse) {
        btnWRecoveryReparse.onclick = () => {
            const rawText = document.getElementById('w-builder-recovery-textarea').value.trim();
            try {
                const parsedWorld = validateWorldData(extractJSON(rawText), 'Generated world');
                state.generatedWorld = parsedWorld;
                
                const warningList = validateWorldPathways(parsedWorld);
                const warningContainer = document.getElementById('w-builder-warning-container');
                if (warningContainer) {
                    warningContainer.innerHTML = '';
                    if (warningList.length > 0) {
                        warningContainer.innerHTML = `
                            <div class="builder-warning-box">
                                <span>⚠️ Pathway Check: ${warningList.length} warning(s) found. Exits will still connect in simulation.</span>
                            </div>
                        `;
                    }
                }

                document.getElementById('w-preview-identity').textContent = `${parsedWorld.name || 'Unnamed'} — ${parsedWorld.description || 'No description'}`;
                document.getElementById('w-preview-locations-count').textContent = `${parsedWorld.locations?.length || 0} locations`;
                document.getElementById('w-preview-entities-count').textContent = `${parsedWorld.entities?.length || 0} items/NPCs`;
                document.getElementById('w-preview-lore-count').textContent = `${parsedWorld.lorebook?.length || 0} entries`;

                document.getElementById('w-builder-progress-box').classList.add('hidden');
                document.getElementById('w-builder-recovery-box').classList.add('hidden');
                document.getElementById('w-builder-preview-box').classList.remove('hidden');
                
                const wDiagnosticEl = document.getElementById('w-builder-error-diagnostic');
                if (wDiagnosticEl) {
                    wDiagnosticEl.classList.add('hidden');
                    wDiagnosticEl.innerHTML = '';
                }
                
                showToast("Universe repaired and parsed successfully!", "success");
            } catch (err) {
                console.error("Manual Reparse Error:", err);
                showToast("Reparsing failed: " + err.message, "error");
                displayJSONErrorDiagnostic('w-', rawText, err.message);
            }
        };
    }
}

// pristine app.js:3736-3809 (World statements only)
async function setupConfigSearchableDropdown(prefix) {
    if (prefix !== 'w-') throw new Error('Stock Worlds only configures the World model picker');
    const inputId = 'w-studio-model';
    const resultsId = 'w-studio-model-results';
    const searchInput = document.getElementById(inputId);
    const resultsDiv = document.getElementById(resultsId);

    if (!searchInput || !resultsDiv) return;

    searchInput.onfocus = async () => {
        const models = await getOpenRouterModels();
        renderResults(models, searchInput.value.trim());
    };

    document.addEventListener('click', (e) => {
        if (!searchInput.contains(e.target) && !resultsDiv.contains(e.target)) {
            resultsDiv.classList.add('hidden');
        }
    });

    searchInput.oninput = async () => {
        const models = await getOpenRouterModels();
        renderResults(models, searchInput.value.trim());
    };

    function renderResults(models, query) {
        resultsDiv.innerHTML = '';
        
        let filtered = models;
        if (query) {
            const q = query.toLowerCase();
            filtered = models.filter(m => 
                m.id.toLowerCase().includes(q) || 
                m.name.toLowerCase().includes(q)
            );
        }

        const displayList = filtered.slice(0, 50);

        if (displayList.length === 0) {
            resultsDiv.innerHTML = '<div style="padding: 10px; color: var(--text-3); font-size: 0.8rem;">No models found</div>';
            resultsDiv.classList.remove('hidden');
            return;
        }

        displayList.forEach(m => {
            const item = document.createElement('div');
            item.className = 'searchable-dropdown-item';
            const name = document.createElement('span');
            name.className = 'model-display-name';
            name.textContent = String(m.name || m.id || 'Unnamed model');
            const id = document.createElement('span');
            id.className = 'model-display-id';
            id.textContent = String(m.id || '');
            item.append(name, id);
            
            item.onclick = async () => {
                searchInput.value = m.id;
                resultsDiv.classList.add('hidden');
                    if (state.editingWorld) state.editingWorld.model = m.id;
                    await fetchModelData(m.id, 'w-', state.editingWorld);
            };
            resultsDiv.appendChild(item);
        });

        resultsDiv.classList.remove('hidden');
    }
}

// pristine app.js:11245-11277 (World branch only)
async function summarizeStory() {
        const world = state.worlds.find(w => w.id === state.activeWorldId);
        const sess = getCurrentWorldSession();
        if (!world || !sess) return showToast('No active world session', 'error');
        if (!sess.history || sess.history.length < 2) return showToast('Not enough history to summarize', 'info');

        showToast('Generating world summary...', 'info');
        const history = sess.history
            .map(m => `${m.role === 'user' ? 'Player' : 'DM'}: ${m.content}`)
            .join('\n\n');

        try {
            const response = await fetch(apiBase() + '/chat/completions', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', ...authHeaders() },
                body: JSON.stringify({
                    model: world.model || state.globalSettings.defaultModel,
                    messages: [
                        { role: 'system', content: `You are "Horde Chronos", the world chronicle keeper. Summarize this adventure concisely and dramatically.\n\nStructure:\n### 📜 THE STORY SO FAR\n[2-3 sentence narrative overview]\n\n### 🔑 KEY DEVELOPMENTS\n- [3 most important events or changes]\n\n### 📍 CURRENT STATE\n- Location, active quests, key NPC status` },
                        { role: 'user', content: `Summarize this world session:\n\n${history}` }
                    ]
                })
            });
            if (!response.ok) throw new Error((await response.json().catch(() => ({}))).error?.message || 'API error');
            const summary = (await response.json()).choices[0].message.content;
            showConfirmModal('World Summary', summary, null, 'Close', 'Dismiss');
        } catch (err) {
            showToast('Summarization failed: ' + err.message, 'error');
        }
        return;
}

// pristine app.js:31791-31850 (World statements only)
function invalidateEpisodicFrom(session, msgIndex) {
    bumpMemoryEpoch(session);
    if (!session) return false;

    let rewindTo = session.lastConsolidatedIndex || 0;
    let droppedAny = false;
    const kept = [];

    for (const m of (session.episodicMemories || [])) {
        const start = (m.startIndex ?? 0);
        const end = (m.endIndex ?? Infinity); // exclusive
        // Memory is stale if its coverage includes msgIndex or extends past it.
        if (end > msgIndex) {
            rewindTo = Math.min(rewindTo, start);
            droppedAny = true;
        } else {
            kept.push(m);
        }
    }

    if (droppedAny) {
        session.episodicMemories = kept;
    }

    if ((session.lastConsolidatedIndex || 0) > msgIndex || droppedAny) {
        session.lastConsolidatedIndex = Math.min(session.lastConsolidatedIndex || 0, rewindTo, msgIndex);
    }
    return droppedAny;
}

// pristine app.js:31913-32078 (World statements only)
async function consolidateSessionEpisodicMemoryRun(session, config) {
    if (!session) return;
    // Race guard: remember the epoch at read time; if a reroll/edit/restore
    // rewrites history while our API calls are in flight, we must not commit.
    const startEpoch = session._memEpoch || 0;

    const messages = session.history;
    if (!messages || messages.length < 2) return;
    
    const lastIdx = session.lastConsolidatedIndex || 0;
    const currentLen = messages.length;
    
    // Consolidate in rolling chunks of 8 messages
    const CONSOLIDATION_CHUNK_SIZE = 8;
    if (currentLen - lastIdx < CONSOLIDATION_CHUNK_SIZE) return;
    
    if (!hasApiCredentials()) {
        console.warn('Consolidation: Skipping - API Key missing.');
        return;
    }
    
    // FIX 1: World sessions use config.title, not config.name
    const configName = config.name || config.title || 'Narrator';

    // Process the next sequential block of unconsolidated messages (up to 40 max)
    const MAX_SLICE = 40;
    const chunkEnd = Math.min(lastIdx + MAX_SLICE, currentLen);
    const slice = messages.slice(lastIdx, chunkEnd);
    console.log(`Consolidation: Archiving messages ${lastIdx}–${chunkEnd} (${slice.length} msgs)`);

    const sliceText = slice.map(m => {
        if (m.role === 'system') return null; // skip injected system blocks
        let prefix = 'Participant';
        if (m.role === 'user') {
            prefix = 'User';
        } else if (m.role === 'assistant' || m.role === 'dm') {
            prefix = configName;
            if (m.charId) {
                const char = state.characters.find(c => c.id === m.charId);
                if (char) prefix = char.name;
            }
        }
        const content = (canonicalMsgText(m)).trim();
        return content ? `${prefix}: ${content}` : null;
    }).filter(Boolean).join('\n\n');

    if (!sliceText) {
        session.lastConsolidatedIndex = chunkEnd;
        return;
    }
    
    try {
        // FIX 3: Use a dedicated fast model — never the character's full model
        // A flash-tier model is sufficient and avoids context limit / cost issues
        const consolidationModel = state.globalSettings?.consolidationModel
            || (isLocalProvider() ? state.globalSettings.defaultModel : 'google/gemini-flash-1.5-8b');

        const response = await fetch(apiBase() + '/chat/completions', {
            method: 'POST',
            headers: {
                ...authHeaders(),
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                model: consolidationModel,
                max_tokens: 500,
                messages: [
                    {
                        role: 'system',
                        content: `You are "Horde Chronos" — a narrative memory archivist.
Summarize the roleplay segment below in AT MOST 3 short sentences (roughly 60 words). Capture only the key events, decisions, secrets revealed, and status changes. Third person, factual, no embellishment. Finish every sentence — never trail off.
Begin your response with: [EPISODIC ARCHIVE]:`
                    },
                    { role: 'user', content: `Roleplay segment:\n\n${sliceText}` }
                ]
            })
        });

        if (!response.ok) {
            const errBody = await response.text();
            throw new Error(`Consolidation API ${response.status}: ${errBody.slice(0, 200)}`);
        }

        const data = await response.json();
        let rawMemory = data.choices?.[0]?.message?.content?.trim();
        if (!rawMemory) throw new Error('Consolidation model returned empty content');
        let summary = rawMemory;
        // Safety net: if the model still overran the budget, trim to the last
        // COMPLETE sentence so we never archive a mid-word fragment like "…while".
        if (data.choices?.[0]?.finish_reason === 'length') {
            summary = trimToLastSentence(summary);
        }
        
        console.log(`Consolidation OK: ${summary.slice(0, 100)}...`);
        
        // Stamp the covered message range so this memory can be invalidated if
        // any of its source messages are later edited, rerolled, or deleted.
        // Commit gate: history was rewritten while we were summarizing —
        // this summary describes an abandoned take. Discard it.
        if ((session._memEpoch || 0) !== startEpoch) {
            console.warn('Consolidation aborted: history changed during archiving (reroll/edit) — summary discarded.');
            return;
        }

        let totalMemories = 0;
            const embedding = await HordeVectorMemory.getCachedEmbedding(summary);
            session.episodicMemories = session.episodicMemories || [];
            session.episodicMemories.push({
                text: summary, embedding,
                embeddingNamespace: embedding ? HordeVectorMemory.namespace() : '',
                createdAt: Date.now(), startIndex: lastIdx, endIndex: chunkEnd
            });
            totalMemories = session.episodicMemories.length;
        session.lastConsolidatedIndex = chunkEnd;

        await saveState();
        // FIX 4: Visible feedback so you know it actually ran
        showToast(`🧠 Memory archived (${totalMemories} active)`, 'info');
        console.log(`Consolidation saved. Total active memories: ${totalMemories}`);
    } catch (e) {
        // Do NOT update lastConsolidatedIndex on failure — will retry next turn
        console.warn(`Consolidation failed (will retry next turn):`, e.message);
    }
}

// pristine app.js:32086-32200 (World statements only)
function setupVectorMemoryViewerEvents() {
    const worldOpenBtn = document.getElementById('world-open-vector-memory-btn');
    const closeBtn = document.getElementById('close-vector-memory-btn');
    const closeFtBtn = document.getElementById('close-vector-memory-ft-btn');
    const overlay = document.getElementById('vector-memory-modal-overlay');
    
    const tabEpisodic = document.getElementById('vector-tab-episodic');
    const tabBiography = document.getElementById('vector-tab-biography');
    
    const searchBtn = document.getElementById('vector-test-search-btn');
    const queryInput = document.getElementById('vector-test-query');
    if (worldOpenBtn) {
        worldOpenBtn.onclick = () => {
            currentVectorTab = 'episodic';
            overlay.classList.remove('hidden');
            updateVectorTabUI();
            renderVectorMemoryList();
        };
    }
    
    const closeModal = () => {
        overlay.classList.add('hidden');
        if (queryInput) queryInput.value = '';
    };
    
    if (closeBtn) closeBtn.onclick = closeModal;
    if (closeFtBtn) closeFtBtn.onclick = closeModal;
    
    if (tabEpisodic) {
        tabEpisodic.onclick = () => {
            currentVectorTab = 'episodic';
            updateVectorTabUI();
            renderVectorMemoryList();
        };
    }
    
    if (tabBiography) {
        tabBiography.onclick = () => {
            currentVectorTab = 'biography';
            updateVectorTabUI();
            renderVectorMemoryList();
        };
    }
    
    if (searchBtn && queryInput) {
        searchBtn.onclick = () => {
            const val = queryInput.value.trim();
            renderVectorMemoryList(val);
        };
        
        queryInput.onkeydown = (e) => {
            if (e.key === 'Enter') {
                const val = queryInput.value.trim();
                renderVectorMemoryList(val);
            }
        };
    }
    // Force Archive Now — bypass 8-turn wait and immediately consolidate all history
    const forceArchiveBtn = document.getElementById('force-archive-now-btn');
    if (forceArchiveBtn) {
        forceArchiveBtn.onclick = async () => {
            forceArchiveBtn.disabled = true;
            forceArchiveBtn.textContent = '⏳ Archiving...';

            try {
                    const world = state.worlds.find(w => w.id === state.activeWorldId);
                    const sess = getCurrentWorldSession();
                    if (!sess || !world) throw new Error('No active world session');
                    // Full rebuild: clear stale memories and re-consolidate from scratch
                    // (otherwise we'd duplicate the entire archive on top of old entries).
                    sess.episodicMemories = [];
                    sess.lastConsolidatedIndex = 0;
                    while (sess.history.length - (sess.lastConsolidatedIndex || 0) >= 8) {
                        await consolidateSessionEpisodicMemory(sess, world);
                    }
                // Refresh the list
                renderVectorMemoryList();
            } catch (e) {
                showToast('Force archive failed: ' + e.message, 'error');
            } finally {
                forceArchiveBtn.disabled = false;
                forceArchiveBtn.textContent = '⚡ Force Archive Now';
            }
        };
    }
}

// pristine app.js:32231-32526 (World statements only)
async function renderVectorMemoryList(filterQuery = "") {
    const listContainer = document.getElementById('vector-memory-list');
    if (!listContainer) return;
    
    listContainer.innerHTML = `<div style="text-align:center; padding:20px; color:var(--text-3);">Loading memories...</div>`;
    let candidates = [];
    // Track the live array backing the episodic tab so cards can edit/delete entries
    currentEpisodicStore = null;
    if (currentVectorTab === 'episodic') {
        // Retrieve rolling episodic summaries
            const sess = getCurrentWorldSession();
            if (sess && sess.episodicMemories) {
                currentEpisodicStore = sess.episodicMemories;
                candidates = sess.episodicMemories.map(m => ({ text: m.text, embedding: m.embedding, source: 'episodic', ref: m }));
            }
    } else {
            const world = state.worlds.find(w => w.id === state.activeWorldId);
            const sess = getCurrentWorldSession();
            if (world && sess) {
                // Return all entities in current location
                const currentLocationId = sess.playerLocation;
                const loc = world.locations.find(l => l.id === currentLocationId);
                const npcs = sessionNpcs(world, sess).filter(e =>
                    sess.entityStates[e.id]?.location === currentLocationId && isNpcActive(sess.entityStates[e.id]));
                
                // Add loc and npcs as lore/bio sources
                if (loc && loc.description) {
                    candidates.push({ text: `[LOCATION: ${loc.name}] ${loc.description}`, source: 'biography' });
                }
                npcs.forEach(n => {
                    if (n.prompt) {
                        candidates.push({ text: `[NPC: ${n.name}] ${n.prompt}`, source: 'biography' });
                    }
                    if (n.memory) {
                        const memArray = Array.isArray(n.memory) ? n.memory : [];
                        memArray.forEach(m => {
                            candidates.push({ text: `[NPC MEMORY: ${n.name}] ${m.text || m}`, embedding: m.embedding, source: 'biography' });
                        });
                    }
                });
            }
    }
    if (candidates.length === 0) {
        listContainer.innerHTML = `<div style="text-align:center; padding:30px; color:var(--text-3); font-style:italic;">No vector memories indexed in this category yet. Summarize the chat or proceed with roleplay to generate them!</div>`;
        return;
    }
    
    let displayList = [];
    
    // If user typed a query, perform a similarity match or keyword fallback match!
    if (filterQuery) {
        listContainer.innerHTML = `<div style="text-align:center; padding:20px; color:var(--text-3);">Calculating cosine similarity scores...</div>`;
        
        try {
            // Check cache for candidates missing embeddings to be fast
            for (const cand of candidates) {
                if (!cand.embedding) {
                    const key = `${HordeVectorMemory.namespace()}|${HordeVectorMemory.hashText(cand.text)}`;
                    if (HordeVectorMemory.cache.has(key)) {
                        cand.embedding = HordeVectorMemory.cache.get(key);
                    }
                }
            }
            
            const queryVec = await HordeVectorMemory.getCachedEmbedding(filterQuery);
            if (queryVec && !HordeVectorMemory.isFallbackActive) {
                displayList = candidates.map(cand => {
                    let score = 0;
                    if (Array.isArray(cand.embedding) && cand.embedding.length > 0
                        && (!cand.embeddingNamespace || cand.embeddingNamespace === HordeVectorMemory.namespace())) {
                        score = cosineSimilarity(queryVec, cand.embedding);
                    }
                    return {
                        text: cand.text,
                        score: score,
                        cached: !!cand.embedding,
                        ref: cand.ref,
                        type: cand.type,
                        status: cand.status,
                        importance: cand.importance,
                        sourceSessionId: cand.sourceSessionId,
                        pinned: cand.pinned
                    };
                });
                displayList.sort((a, b) => b.score - a.score);
            } else {
                // Fallback concept matching
                const cLower = filterQuery.toLowerCase();
                displayList = candidates.map(cand => {
                    const score = cand.text.toLowerCase().includes(cLower) ? 0.99 : 0.0;
                    return { ...cand, text: cand.text, score, cached: false, ref: cand.ref };
                });
                displayList.sort((a, b) => b.score - a.score);
            }
        } catch (e) {
            console.warn("Inspector search failed, falling back to keyword scoring:", e);
            const cLower = filterQuery.toLowerCase();
            displayList = candidates.map(cand => {
                const score = cand.text.toLowerCase().includes(cLower) ? 0.99 : 0.0;
                return { ...cand, text: cand.text, score, cached: false, ref: cand.ref };
            });
            displayList.sort((a, b) => b.score - a.score);
        }
    } else {
        displayList = candidates.map(c => ({
            text: c.text,
            score: null,
            cached: !!c.embedding,
            ref: c.ref,
            type: c.type,
            status: c.status,
            importance: c.importance,
            sourceSessionId: c.sourceSessionId,
            pinned: c.pinned
        }));
    }
    
    listContainer.innerHTML = "";
    displayList.forEach(item => {
        const card = document.createElement('div');
        card.style.background = 'var(--surface)';
        card.style.border = '1px solid var(--border)';
        card.style.borderRadius = '8px';
        card.style.padding = '12px 16px';
        card.style.display = 'flex';
        card.style.flexDirection = 'column';
        card.style.gap = '8px';
        card.style.boxShadow = '0 2px 8px rgba(0,0,0,0.1)';
        card.style.transition = 'transform 0.2s, border-color 0.2s';
        
        // Dynamic hover effects
        card.onmouseenter = () => {
            card.style.borderColor = 'var(--accent)';
            card.style.transform = 'translateY(-1px)';
        };
        card.onmouseleave = () => {
            card.style.borderColor = 'var(--border)';
            card.style.transform = 'none';
        };
        
        // HSL Tag styling for score
        let scoreTag = "";
        if (item.score !== null) {
            const pct = Math.round(item.score * 100);
            let color = 'var(--red)';
            if (pct >= 70) color = 'var(--success)';
            else if (pct >= 40) color = 'var(--warning)';
            
            scoreTag = `<span style="font-size:0.7rem; font-weight:800; font-family:monospace; background:rgba(0,0,0,0.2); color:${color}; padding:2px 8px; border-radius:10px; border:1px solid ${color};">MATCH ${pct}%</span>`;
        }
        
        const cacheTag = item.cached
            ? `<span style="font-size:0.6rem; font-weight:800; text-transform:uppercase; color:var(--success); opacity:0.85;">⚡ EMBEDDED</span>`
            : `<span style="font-size:0.6rem; font-weight:800; text-transform:uppercase; color:var(--text-3); opacity:0.6;">⏳ RAW TEXT</span>`;

        // Editable only for episodic memories (which we have a live ref to)
        const editable = currentVectorTab === 'episodic' && item.ref && currentEpisodicStore;
        const escaped = (item.text || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

        const actionBtns = editable ? `
            <div style="display:flex; gap:6px;">
                <button class="tool-btn epi-pin-btn" title="Keep this memory in recall" style="font-size:11px; padding:2px 8px;">${item.ref?.pinned ? '★ Pinned' : '☆ Pin'}</button>
                <button class="tool-btn epi-edit-btn" title="Edit memory" style="font-size:11px; padding:2px 8px;">✎ Edit</button>
                <button class="tool-btn tool-btn-danger epi-del-btn" title="Delete memory" style="font-size:11px; padding:2px 8px;">✕</button>
            </div>` : '';

        const metadata = item.ref ? [
            String(item.ref.type || 'episode').replace('_', ' '),
            item.ref.status || 'active',
            `importance ${Math.round((Number(item.ref.importance) || 0.5) * 100)}%`,
            item.ref.sourceSessionId ? `source ${item.ref.sourceSessionId}` : '',
            Number.isFinite(Number(item.ref.startIndex)) ? `messages ${item.ref.startIndex}–${item.ref.endIndex ?? '?'}` : ''
        ].filter(Boolean).join(' · ') : '';

        card.innerHTML = `
            <div style="display:flex; justify-content:space-between; align-items:center; border-bottom:1px solid var(--border2); padding-bottom:6px;">
                <div style="display:flex; gap:8px; align-items:center;">${cacheTag}${scoreTag}</div>
                ${actionBtns}
            </div>
            ${metadata ? `<div style="font-size:0.68rem; color:var(--text-3); text-transform:uppercase; letter-spacing:.04em;">${escapeHTML(metadata)}</div>` : ''}
            <div class="epi-text" style="font-size:0.9rem; line-height:1.5; color:var(--text); white-space:pre-wrap;">${escaped}</div>
            ${editable ? `<textarea class="form-textarea epi-edit-box" rows="6" style="display:none;">${escaped}</textarea>` : ''}
        `;

        if (editable) {
            const ref = item.ref;
            const textDiv = card.querySelector('.epi-text');
            const box = card.querySelector('.epi-edit-box');
            const editBtn = card.querySelector('.epi-edit-btn');
            const delBtn = card.querySelector('.epi-del-btn');
            const pinBtn = card.querySelector('.epi-pin-btn');

            pinBtn.onclick = async () => {
                ref.pinned = !ref.pinned;
                ref.updatedAt = Date.now();
                await saveState();
                renderVectorMemoryList(filterQuery);
            };

            delBtn.onclick = async () => {
                const i = currentEpisodicStore.indexOf(ref);
                if (i === -1) return;
                currentEpisodicStore.splice(i, 1);
                await saveState();
                renderVectorMemoryList(filterQuery);
                showToast('Memory deleted', 'success');
            };

            editBtn.onclick = async () => {
                const editing = box.style.display !== 'none';
                if (!editing) {
                    textDiv.style.display = 'none';
                    box.style.display = 'block';
                    box.focus();
                    editBtn.textContent = '✓ Save';
                } else {
                    const newText = box.value.trim();
                    if (!newText) return showToast('Memory text cannot be empty', 'error');
                    ref.text = newText;
                    try {
                        ref.embedding = await getEmbedding(newText);
                        ref.embeddingNamespace = HordeVectorMemory.namespace();
                        ref.updatedAt = Date.now();
                    } catch (e) {
                        console.warn('Re-embed failed, keeping text only:', e);
                        delete ref.embedding;
                    }
                    await saveState();
                    renderVectorMemoryList(filterQuery);
                    showToast('Memory updated', 'success');
                }
            };
        }

        listContainer.appendChild(card);
    });
}

