// pristine app.js:3435-3444
function worldMediaHash(data) {
    const text = String(data || '');
    let hash = 2166136261;
    const stride = Math.max(1, Math.floor(text.length / 4096));
    for (let i = 0; i < text.length; i += stride) {
        hash ^= text.charCodeAt(i);
        hash = Math.imul(hash, 16777619);
    }
    return `${text.length.toString(36)}_${(hash >>> 0).toString(36)}`;
}

// pristine app.js:3446-3479
function addWorldMediaAsset(world, data, kind, label = '', metadata = {}) {
    normalizeWorldPresentation(world);
    const source = String(data || '');
    if (!/^data:image\/[a-z0-9.+-]+(?:;[^,]*)?,/i.test(source)) {
        throw new Error('World media must be embedded image data so exported worlds remain portable.');
    }
    if (source.length > WORLD_MEDIA_ASSET_BYTES_LIMIT) {
        throw new Error('The normalized image is still too large for a portable world asset.');
    }
    const hash = worldMediaHash(source);
    const existing = world.mediaAssets.find(asset => asset.hash === hash);
    if (existing) return existing.id;
    if (world.mediaAssets.length >= WORLD_MEDIA_ASSET_LIMIT) {
        throw new Error(`This world has reached the ${WORLD_MEDIA_ASSET_LIMIT.toLocaleString()} media-asset limit.`);
    }
    const existingBytes = world.mediaAssets.reduce((sum, asset) => sum + String(asset.data || '').length, 0);
    if (existingBytes + source.length > 512_000_000) {
        throw new Error('This world has reached the 512 MB portable-media limit. Remove unused visuals before adding more.');
    }
    const id = `media_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 9)}`;
    world.mediaAssets.push({
        id,
        kind: String(kind || 'image').slice(0, 80),
        label: String(label || '').slice(0, 240),
        data: source,
        hash,
        createdAt: Date.now(),
        generated: metadata.generated === true,
        model: String(metadata.model || '').slice(0, 500),
        prompt: String(metadata.prompt || '').slice(0, 8000)
    });
    if ((state.worlds || []).includes(world)) worldMediaDirty = true;
    return id;
}

// pristine app.js:3481-3488
function worldMediaReferenceIds(world) {
    const ids = new Set();
    const add = value => { if (typeof value === 'string' && value) ids.add(value); };
    add(world?.presentation?.mapSkinAssetId);
    (world?.locations || []).forEach(location => add(location?.visuals?.backgroundAssetId));
    (world?.entities || []).forEach(entity => add(entity?.visuals?.portraitAssetId));
    return ids;
}

// pristine app.js:3490-3498
function pruneWorldMediaAssets(world) {
    normalizeWorldPresentation(world);
    const referenced = worldMediaReferenceIds(world);
    const before = world.mediaAssets.length;
    world.mediaAssets = world.mediaAssets.filter(asset => referenced.has(asset.id));
    const removed = before - world.mediaAssets.length;
    if (removed && (state.worlds || []).includes(world)) worldMediaDirty = true;
    return removed;
}

// pristine app.js:3500-3504
function worldMediaSummary(world) {
    normalizeWorldPresentation(world);
    const bytes = world.mediaAssets.reduce((sum, asset) => sum + String(asset.data || '').length, 0);
    return { count: world.mediaAssets.length, bytes };
}

// pristine app.js:3506-3511
function formatByteSize(bytes) {
    const value = Math.max(0, Number(bytes) || 0);
    if (value < 1024) return `${value} B`;
    if (value < 1024 * 1024) return `${(value / 1024).toFixed(1)} KB`;
    return `${(value / (1024 * 1024)).toFixed(1)} MB`;
}

// pristine app.js:3577-3669
function verifyModelCapabilities(model, prefix) {
    const badge = document.getElementById(prefix + 'builder-verification-badge');
    const card = document.getElementById(prefix + 'builder-verification-card');
    const detailContext = document.getElementById(prefix + 'builder-detail-context');
    const detailPrice = document.getElementById(prefix + 'builder-detail-price');
    const detailTools = document.getElementById(prefix + 'builder-detail-tools');
    const detailJson = document.getElementById(prefix + 'builder-detail-json');

    if (!badge || !card || !detailContext || !detailPrice || !detailTools || !detailJson) return;

    if (!model) {
        badge.textContent = "Unknown";
        badge.className = "verification-badge badge-weak";
        card.className = "verification-card tier-weak";
        detailContext.textContent = "❓ Context: —";
        detailPrice.textContent = "❓ Price: —";
        detailTools.textContent = "❓ Tool Calling";
        detailTools.className = "verification-detail-item";
        detailJson.textContent = "❓ Structured JSON";
        detailJson.className = "verification-detail-item";
        return;
    }

    const context = model.context_length || 8192;
    const params = model.supported_parameters || [];
    const pricing = model.pricing || {};
    const promptPrice = Number.isFinite(parseFloat(pricing.prompt)) ? (parseFloat(pricing.prompt) * 1000000).toFixed(2) : '—';
    const completionPrice = Number.isFinite(parseFloat(pricing.completion)) ? (parseFloat(pricing.completion) * 1000000).toFixed(2) : '—';

    const hasTools = params.includes('tools') || params.includes('tool_choice');
    const hasJson = params.includes('response_format') || params.includes('structured_outputs');

    detailContext.textContent = `👁️ Context: ${Math.round(context / 1000)}k tokens`;
    detailPrice.textContent = `💰 $${promptPrice} / $${completionPrice} (per M)`;

    if (hasTools) {
        detailTools.textContent = "✅ Tool Calling";
        detailTools.className = "verification-detail-item supported";
    } else {
        detailTools.textContent = "❌ Tool Calling";
        detailTools.className = "verification-detail-item unsupported";
    }

    if (hasJson) {
        detailJson.textContent = "✅ Structured JSON";
        detailJson.className = "verification-detail-item supported";
    } else {
        detailJson.textContent = "❌ Structured JSON";
        detailJson.className = "verification-detail-item unsupported";
    }

    if (hasTools && hasJson && context >= 32000) {
        badge.textContent = "Elite Agent (Class S)";
        badge.className = "verification-badge badge-elite";
        card.className = "verification-card tier-elite";
    } else if (hasTools || hasJson) {
        badge.textContent = "Capable (Class A)";
        badge.className = "verification-badge badge-capable";
        card.className = "verification-card tier-capable";
    } else {
        badge.textContent = "Not Recommended (Class C)";
        badge.className = "verification-badge badge-weak";
        card.className = "verification-card tier-weak";
    }

    // Dynamically adjust the context limit slider max and stepping
    const sliderId = prefix === 'w-' ? 'w-studio-context-size' : 'studio-context-size';
    const slider = document.getElementById(sliderId);
    if (slider && model && model.context_length) {
        const physicalLimit = model.context_length;
        slider.max = physicalLimit;
        
        if (physicalLimit <= 32768) {
            slider.step = 1024;
        } else if (physicalLimit <= 131072) {
            slider.step = 2048;
        } else if (physicalLimit <= 524288) {
            slider.step = 8192;
        } else {
            slider.step = 16384;
        }

        // Clamp value if it exceeds new maximum context
        if (parseInt(slider.value) > physicalLimit) {
            slider.value = physicalLimit;
        }
        
        // Refresh slider badge & readout
        const valId = prefix === 'w-' ? 'w-studio-context-size-val' : 'studio-context-size-val';
        const badgeId = prefix === 'w-' ? 'w-studio-context-size-badge' : 'studio-context-size-badge';
        updateContextSliderUI(sliderId, valId, badgeId);
    }
}

// pristine app.js:3671-3734
async function setupSearchableDropdown(prefix) {
    const searchInput = document.getElementById(prefix + 'builder-model-search');
    const resultsDiv = document.getElementById(prefix + 'builder-model-results');

    if (!searchInput || !resultsDiv) return;

    searchInput.onfocus = async () => {
        const models = await getOpenRouterModels();
        renderResults(models, searchInput.value.trim());
    };

    document.addEventListener('click', (e) => {
        if (!searchInput.contains(e.target) && !resultsDiv.contains(e.target)) {
            resultsDiv.classList.add('hidden');
        }
    });

    searchInput.oninput = async () => {
        const models = await getOpenRouterModels();
        renderResults(models, searchInput.value.trim());
    };

    function renderResults(models, query) {
        resultsDiv.innerHTML = '';
        
        let filtered = models;
        if (query) {
            const q = query.toLowerCase();
            filtered = models.filter(m => 
                m.id.toLowerCase().includes(q) || 
                m.name.toLowerCase().includes(q)
            );
        }

        const displayList = filtered.slice(0, 50);

        if (displayList.length === 0) {
            resultsDiv.innerHTML = '<div style="padding: 10px; color: var(--text-3); font-size: 0.8rem;">No models found</div>';
            resultsDiv.classList.remove('hidden');
            return;
        }

        displayList.forEach(m => {
            const item = document.createElement('div');
            item.className = 'searchable-dropdown-item';
            const name = document.createElement('span');
            name.className = 'model-display-name';
            name.textContent = String(m.name || m.id || 'Unnamed model');
            const id = document.createElement('span');
            id.className = 'model-display-id';
            id.textContent = String(m.id || '');
            item.append(name, id);
            
            item.onclick = () => {
                searchInput.value = m.id;
                resultsDiv.classList.add('hidden');
                verifyModelCapabilities(m, prefix);
            };
            resultsDiv.appendChild(item);
        });

        resultsDiv.classList.remove('hidden');
    }
}

