function setBuilderStep(stepId, status) {
    const stepEl = document.getElementById(stepId);
    if (!stepEl) return;
    
    stepEl.classList.remove('pending', 'active', 'success');
    stepEl.classList.add(status);
    
    const icon = stepEl.querySelector('.step-icon');
    if (icon) {
        if (status === 'success') {
            icon.innerHTML = '✓';
        } else if (status === 'active') {
            icon.innerHTML = '●';
        } else {
            const steps = Array.from(stepEl.parentNode.children);
            const index = steps.indexOf(stepEl);
            icon.innerHTML = (index + 1).toString();
        }
    }
}

// pristine app.js:3832-3920
function dirtyJSONRepair(s) {
    s = s.trim();
    // Strip out markdown code block characters if present
    s = s.replace(/^```json\s*/i, '');
    s = s.replace(/^```\s*/i, '');
    s = s.replace(/\s*```$/, '');
    
    const firstBrace = s.indexOf('{');
    if (firstBrace === -1) return s;
    s = s.substring(firstBrace);
    
    let insideString = false;
    let escaped = false;
    let clean = "";
    let openBrackets = [];
    
    for (let i = 0; i < s.length; i++) {
        const char = s[i];
        
        if (insideString) {
            if (escaped) {
                clean += char;
                escaped = false;
            } else if (char === '\\') {
                clean += char;
                escaped = true;
            } else if (char === '"') {
                insideString = false;
                clean += char;
            } else if (char === '\n') {
                clean += '\\n'; // escape actual newlines inside double quotes
            } else if (char === '\r') {
                clean += '\\r';
            } else if (char === '\t') {
                clean += '\\t';
            } else {
                clean += char;
            }
        } else {
            if (char === '"') {
                insideString = true;
                clean += char;
            } else if (char === '{') {
                openBrackets.push('{');
                clean += char;
            } else if (char === '[') {
                openBrackets.push('[');
                clean += char;
            } else if (char === '}') {
                if (clean.trim().endsWith(',')) {
                    clean = clean.trim().slice(0, -1);
                }
                if (openBrackets.length > 0 && openBrackets[openBrackets.length - 1] === '{') {
                    openBrackets.pop();
                }
                clean += char;
            } else if (char === ']') {
                if (clean.trim().endsWith(',')) {
                    clean = clean.trim().slice(0, -1);
                }
                if (openBrackets.length > 0 && openBrackets[openBrackets.length - 1] === '[') {
                    openBrackets.pop();
                }
                clean += char;
            } else {
                clean += char;
            }
        }
    }
    
    if (insideString) {
        clean += '"';
    }
    
    if (clean.trim().endsWith(',')) {
        clean = clean.trim().slice(0, -1);
    }
    
    while (openBrackets.length > 0) {
        const open = openBrackets.pop();
        if (open === '{') {
            clean += '}';
        } else if (open === '[') {
            clean += ']';
        }
    }
    
    return clean;
}

// pristine app.js:3922-3945
function extractJSON(text) {
    try {
        // Try repairing first using the advanced repair state-machine
        const repaired = dirtyJSONRepair(text);
        return JSON.parse(repaired);
    } catch (e) {
        // Fallback: if repaired fails, try extracting first/last brace and a standard cleanup
        try {
            const firstBrace = text.indexOf('{');
            const lastBrace = text.lastIndexOf('}');
            if (firstBrace === -1 || lastBrace === -1) {
                throw new Error("Could not find a valid JSON object block in response.");
            }
            const jsonStr = text.substring(firstBrace, lastBrace + 1);
            const cleaned = jsonStr
                .replace(/,\s*([}\]])/g, '$1')
                .replace(/(\r\n|\n|\r)/gm, "\\n"); // escape instead of replacing with space!
            return JSON.parse(cleaned);
        } catch (originalErr) {
            // Throw original error so it triggers recovery UI
            throw new Error(originalErr.message);
        }
    }
}

// pristine app.js:3947-4009
function displayJSONErrorDiagnostic(prefix, rawText, errorMessage) {
    const diagnosticEl = document.getElementById(prefix + 'builder-error-diagnostic');
    if (!diagnosticEl) return;
    
    diagnosticEl.classList.remove('hidden');
    
    let position = -1;
    const posMatch = errorMessage.match(/position (\d+)/i);
    if (posMatch) {
        position = parseInt(posMatch[1], 10);
    }
    
    if (position !== -1 && position >= 0 && position <= rawText.length) {
        const textBefore = rawText.substring(0, position);
        const lines = textBefore.split('\n');
        const lineNum = lines.length;
        const colNum = lines[lines.length - 1].length + 1;
        
        const start = Math.max(0, position - 40);
        const end = Math.min(rawText.length, position + 40);
        const snippetBefore = rawText.substring(start, position);
        const offendingChar = rawText.charAt(position) || ' ';
        const snippetAfter = rawText.substring(position + 1, end);
        
        diagnosticEl.innerHTML = `
            <div style="font-size: 0.85rem; font-weight: bold; color: #FF809B; margin-bottom: 8px;">
                ❌ Parsing Error: ${escapeHTML(errorMessage)}
            </div>
            <div style="font-size: 0.75rem; color: var(--text-2); margin-bottom: 10px;">
                Location: <strong>Line ${lineNum}</strong>, <strong>Column ${colNum}</strong> (Character Index ${position})
            </div>
            <div style="background: #04040a; border: 1px solid rgba(230, 57, 70, 0.3); border-left: 3px solid #E63946; padding: 10px; font-family: monospace; font-size: 0.75rem; white-space: pre-wrap; word-break: break-all; color: #888; border-radius: 4px;">
                ...${escapeHTML(snippetBefore)}<span style="background: rgba(230, 57, 70, 0.4); color: #FFF; font-weight: bold; padding: 2px 4px; border-radius: 2px; border: 1px solid #E63946; text-shadow: 0 0 5px #E63946; font-size: 0.8rem;">${escapeHTML(offendingChar)}</span>${escapeHTML(snippetAfter)}...
            </div>
            <div style="font-size: 0.7rem; color: var(--text-3); margin-top: 8px; line-height: 1.3;">
                💡 <strong>Auto-focused:</strong> The editor has scrolled to the error and highlighted the character. Look around the red character for a missing quote, unclosed bracket/brace, or a duplicate comma.
            </div>
        `;
        
        // Auto-select and scroll textarea to error
        const textarea = document.getElementById(prefix + 'builder-recovery-textarea');
        if (textarea) {
            setTimeout(() => {
                textarea.focus();
                textarea.setSelectionRange(position, position + 1);
                
                // Estimate scroll position based on line number
                const lineCount = textBefore.split('\n').length;
                const lineHeight = 16;
                textarea.scrollTop = Math.max(0, (lineCount - 4) * lineHeight);
            }, 100);
        }
    } else {
        diagnosticEl.innerHTML = `
            <div style="font-size: 0.85rem; font-weight: bold; color: #FF809B; margin-bottom: 4px;">
                ❌ Parsing Error: ${escapeHTML(errorMessage)}
            </div>
            <div style="font-size: 0.75rem; color: var(--text-2);">
                Unable to locate the exact character position in the raw response text. Please check for formatting integrity.
            </div>
        `;
    }
}

// pristine app.js:4011-4050
function validateWorldPathways(world) {
    const warnings = [];
    if (!world.locations || world.locations.length === 0) return warnings;

    const locMap = {};
    world.locations.forEach(l => {
        if (l.name) locMap[l.name.toLowerCase()] = l;
        if (l.id) locMap[l.id.toLowerCase()] = l;
    });

    world.locations.forEach(l => {
        const exits = l.exits || [];
        exits.forEach(exitStr => {
            const text = typeof exitStr === 'string' ? exitStr : (exitStr.text || "");
            const target = getExitTargetName(exitStr);
            if (!target) return;
            const dest = locMap[target.toLowerCase()];
            
            if (!dest) {
                warnings.push(`Location "${l.name || 'Unnamed'}" exits to non-existent "${text}"`);
            } else {
                const destExits = dest.exits || [];
                const hasWayBack = destExits.some(de => {
                    const deTarget = getExitTargetName(de);
                    if (!deTarget) return false;
                    const sourceName = (l.name || "").toLowerCase();
                    const sourceId = (l.id || "").toLowerCase();
                    return (sourceName && deTarget.toLowerCase() === sourceName) || 
                           (sourceId && deTarget.toLowerCase() === sourceId);
                });
                
                if (!hasWayBack) {
                    warnings.push(`Uni-directional path: "${l.name || 'Unnamed'}" exits to "${dest.name || 'Unnamed'}", but "${dest.name || 'Unnamed'}" has no way back.`);
                }
            }
        });
    });

    return warnings;
}

