// pristine app.js:25958-25962
function livingClamp(value, min, max) {
    const n = Number(value);
    const fallback = min <= 0 && max >= 0 ? 0 : min;
    return Math.max(min, Math.min(max, Number.isFinite(n) ? n : fallback));
}

