function livingId(prefix, value) {
    const clean = String(value || '').trim().toLowerCase()
        .replace(/[^a-z0-9]+/g, '_')
        .replace(/^_+|_+$/g, '')
        .slice(0, 48);
    return `${prefix}_${clean || Math.random().toString(36).slice(2, 10)}`;
}

